using System.ComponentModel.DataAnnotations;
using BofcBackend.Api.Domain.Entities;
using BofcBackend.Api.Features.Settings.Models;

// SPEC: spec-a6f59e - "Auto generated match number" is an integer from 1 to 8, default 2: a
// never-saved settings row reads 2, and PUT /settings rejects 0 and 9 through the request's
// [Range] (the [ApiController] model validation that returns 400) while 1 to 8 pass.
public static class AutoGeneratedMatchNumberTests
{
    public static (string Name, Func<Task> Run)[] All =>
    [
        ("a never-saved settings row has auto generated match number 2", () =>
        {
            var settings = new SystemSettings { Id = 1 };
            if (settings.AutoGeneratedMatchNumber != 2)
            {
                throw new Exception($"expected 2, got {settings.AutoGeneratedMatchNumber}");
            }
            return Task.CompletedTask;
        }),
        ("an update request that leaves the field out binds the default 2", () =>
        {
            var request = new UpdateSystemSettingsRequest();
            if (request.AutoGeneratedMatchNumber != 2)
            {
                throw new Exception($"expected 2, got {request.AutoGeneratedMatchNumber}");
            }
            return Task.CompletedTask;
        }),
        ("an update request with 0 or 9 fails validation", () =>
        {
            foreach (var value in new[] { 0, 9, -1 })
            {
                if (IsValid(value))
                {
                    throw new Exception($"expected {value} to be rejected");
                }
            }
            return Task.CompletedTask;
        }),
        ("an update request with 1, 2 or 8 passes validation", () =>
        {
            foreach (var value in new[] { 1, 2, 8 })
            {
                if (!IsValid(value))
                {
                    throw new Exception($"expected {value} to be accepted");
                }
            }
            return Task.CompletedTask;
        }),
    ];

    private static bool IsValid(int autoGeneratedMatchNumber)
    {
        var request = new UpdateSystemSettingsRequest { AutoGeneratedMatchNumber = autoGeneratedMatchNumber };
        var results = new List<ValidationResult>();
        var valid = Validator.TryValidateObject(request, new ValidationContext(request), results, validateAllProperties: true);
        // Only this field's result counts - a failure elsewhere in the request would hide what's under test.
        return valid || results.All(r => !r.MemberNames.Contains(nameof(UpdateSystemSettingsRequest.AutoGeneratedMatchNumber)));
    }
}
